/**
 * Target Leading - AI aim prediction for projectile weapons
 *
 * Calculates the aim position that accounts for projectile travel time,
 * predicting where the target will be when the projectile arrives.
 *
 * @module @three-blocks/pro/weapons/ai/targetLeading
 * @private
 */
/**
 * Calculate the aim position for hitting a moving target with a projectile.
 *
 * Uses first-order prediction: assumes target continues at constant velocity.
 * For ballistic projectiles, this provides a good approximation.
 *
 * @param {Object} shooterPos - Shooter position { x, y, z }
 * @param {Object} targetPos - Target current position { x, y, z }
 * @param {Object} targetVel - Target velocity { x, y, z } (units/sec)
 * @param {number} projectileSpeed - Projectile speed in units/sec
 * @returns {Object} Aim position { x, y, z }
 *
 * @example
 * ```js
 * const aimPoint = calcLeadTarget(
 *   { x: 0, y: 1, z: 0 },     // Shooter position
 *   { x: 10, y: 1, z: 5 },    // Target position
 *   { x: 5, y: 0, z: 0 },     // Target moving at 5 units/sec on X
 *   40                         // Arrow speed 40 units/sec
 * );
 * ```
 */
export function calcLeadTarget(shooterPos: any, targetPos: any, targetVel: any, projectileSpeed: number): any;
/**
 * Calculate the aim direction for hitting a moving target, accounting for gravity.
 *
 * For ballistic projectiles, this calculates the launch angle needed to hit
 * the predicted intercept point.
 *
 * @param {Object} shooterPos - Shooter position { x, y, z }
 * @param {Object} targetPos - Target current position { x, y, z }
 * @param {Object} targetVel - Target velocity { x, y, z }
 * @param {number} projectileSpeed - Projectile speed
 * @param {number} gravity - Gravity value (positive = down)
 * @returns {Object} Aim direction { x, y, z } (normalized)
 */
export function calcBallisticLeadDirection(shooterPos: any, targetPos: any, targetVel: any, projectileSpeed: number, gravity: number): any;
